// Masjids for /mosque-directory and /mosque/:id.
// - Masjid Connect (public, read-only API): masjids registered and kept up to date by
//   their own staff on alexa.imuslimlife.com. GET /v1/alexa/masjids and /v1/alexa/masjids/:id.
// - /masjids/index.json: every masjid with a static page (OpenStreetMap + Masjid Connect),
//   written nightly by scripts/city-pages/masjids.mjs. Short keys:
//   { n: name, u: url, t: town, r: region, c: 'us' | 'ca', la, lo, k?: 'musalla', d?: denomination, v?: Masjid Connect id }
import apiConfig from '../config/apiConfig';

async function getJson(path) {
    const response = await fetch(`${apiConfig.baseUrl}${path}`);
    const body = await response.json().catch(() => null);
    if (!response.ok) {
        const error = new Error(body?.error || `HTTP ${response.status}`);
        error.status = response.status;
        throw error;
    }
    return body?.data;
}

/** Active Masjid Connect masjids: [{ id, name, city, address }], sorted by name. */
export async function listMasjids() {
    const data = await getJson('/alexa/masjids');
    return Array.isArray(data?.masjids) ? data.masjids : [];
}

/** One masjid: { masjid, today: { prayers, jumuah, ... }, followers }. */
export function getMasjid(id) {
    return getJson(`/alexa/masjids/${encodeURIComponent(id)}`);
}

// The static index lives on the site itself; in development read the live one.
const INDEX_URL = process.env.NODE_ENV === 'production' ? '/masjids/index.json' : 'https://imuslimlife.com/masjids/index.json';

/** Every listed masjid (static index). */
export async function listDirectory() {
    const response = await fetch(INDEX_URL);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const list = await response.json();
    return Array.isArray(list) ? list : [];
}

/** Claim / add form → POST /v1/alexa/masjid-requests. Throws with the API's message. */
export async function submitMasjidRequest(body) {
    const response = await fetch(`${apiConfig.baseUrl}/alexa/masjid-requests`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
    });
    const json = await response.json().catch(() => null);
    if (response.status === 429) throw new Error('Too many requests from your connection. Please try again in 15 minutes.');
    if (!response.ok) throw new Error(json?.error || 'Could not send. Please try again.');
    return json?.data;
}

export const MASJID_SIGNUP_EMAIL = 'info@yzinfotech.com';
